def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        return False
    if statusCode == 400 and responseBody.get("code") == 40001 and "验证码" in str(responseBody.get("message", "")):
        raise Blocked("登录首先被验证码校验拦截，未验证未注册身份拒绝；检查登录验证码设置差异")
    data = responseBody.get("data")
    no_tokens = not isinstance(data, dict) or (not data.get("accessToken") and not data.get("refreshToken"))
    return statusCode == 401 and responseBody.get("code") == 40101 and responseBody.get("message") == "身份未注册" and no_tokens
